package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.snapshot.PersonSnapshotService;
import org.springframework.context.annotation.Lazy;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Loads sheets by id; a sheet never loaded before is started empty. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Rollup rollup;
    private final Audit audit;

    private final PeriodService periods;
    private final ClaimRepository claims;
    private final PersonSnapshotService snapshots;
    private final RoleService roles;

    // The period and role services load sheets through this one, so they are taken lazily.
    public SheetService(SheetRepository sheets, Rollup rollup, Audit audit, @Lazy PeriodService periods,
            ClaimRepository claims, PersonSnapshotService snapshots, @Lazy RoleService roles) {
        this.roles = roles;
        this.sheets = sheets;
        this.snapshots = snapshots;
        this.claims = claims;
        this.rollup = rollup;
        this.audit = audit;
        this.periods = periods;
    }

    /** The sheet with this id, re-read from the store; started empty if it has never been loaded. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
            } catch (DataIntegrityViolationException raced) {
                // Another user started the same sheet at the same moment: theirs stands.
                return sheets.findById(id).orElseThrow(() -> raced);
            }
        });
    }

    /** The sheet's policy versions, oldest first, each with how many of its claims (not deleted) have it as their
     *  policy version (the one in force on the claim's date); starting the sheet if it has never been loaded. */
    @Transactional
    public List<SheetController.PolicyLineView> policyLines(String id, String user) {
        Sheet sheet = load(id, user);
        Map<Integer, Long> counts = claims.findBySheetIdOrderByListedDescIdDesc(id).stream()
                .filter(c -> c.getStatus() != ClaimStatus.DELETED)
                .collect(Collectors.groupingBy(c -> sheet.policyVersionOn(c.getDate()), Collectors.counting()));
        List<PolicyVersion> versions = sheet.getPolicyVersions();
        return IntStream.range(0, versions.size())
                .mapToObj(i -> new SheetController.PolicyLineView(i + 1, versions.get(i).getKey(),
                        versions.get(i).getFrom(), versions.get(i).getValue(), counts.getOrDefault(i + 1, 0L)))
                .toList();
    }

    /** The sheet's today, or null for a sheet never loaded. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElse(null);
    }

    /** Whether the sheet is archived; a sheet never loaded is not. */
    @Transactional(readOnly = true)
    public boolean isArchived(String id) {
        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
    }
    public SheetView load(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        Sheet live = sheets.load(id, user);
        return asOf == null ? SheetView.of(live) : SheetView.of(history.sheetAsOf(live, asOf), asOf);
    }

    /** The sheet's policy versions, oldest first, each with how many claims have it as their policy version. */
    @GetMapping("/{id}/policy-versions")
    public List<PolicyLineView> policyVersions(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return sheets.policyLines(id, user);
    }

    /** Archive the sheet: a steward only. */
    @PostMapping("/{id}/archive")
    public SheetView archive(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
import { Component, inject, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { PolicyLine, Sheets } from '../../core/sheet';

// The sheet's policy versions: one line per version, oldest first, as its number, its from-date ("start" when it
// counts always), its setting=value and how many claims have it as their policy version.
@Component({
  selector: 'app-policy-viewer',
  template: `
    <section aria-labelledby="policy-heading">
      <h3 id="policy-heading">Policy versions</h3>
      <button type="button" data-testid="policy-show" [disabled]="loading()" (click)="show()">Show policy versions</button>
      @if (error(); as err) {
        <p role="alert" data-testid="policy-error">{{ err }}</p>
      }
      <ul aria-label="Policy versions, oldest first">
        @for (line of lines(); track $index) {
          <li data-testid="policy-line">{{ line }}</li>
        }
      </ul>
    </section>
  `,
})
export class PolicyViewerPanel {
  private readonly sheets = inject(Sheets);

  protected readonly lines = signal<string[]>([]);
  protected readonly error = signal<string | null>(null);
  protected readonly loading = signal(false);

  constructor() {
    // Another sheet's policy versions are not left showing once a sheet is (re)loaded.
    toObservable(this.sheets.loaded)
      .pipe(takeUntilDestroyed())
      .subscribe(() => {
        this.lines.set([]);
        this.error.set(null);
      });
  }

  protected show(): void {
    if (this.loading()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.loading.set(true);
    this.lines.set([]);
    this.sheets.policyLines(sheet.id).subscribe({
      next: (lines) => {
        this.loading.set(false);
        this.lines.set(lines.map(lineOf));
      },
      error: () => {
        this.loading.set(false);
        this.error.set('Could not read the policy versions.');
      },
    });
  }
}

function lineOf(v: PolicyLine): string {
  return `${v.version} ${v.from ?? 'start'} ${v.key}=${v.value ?? ''} ${v.claims}`;
}
